use crate::usermode;
use core::time::Duration;

/// 시스템 호출 인수 구조 (타입 안전성)
#[repr(C)]
#[derive(Clone, Copy, Debug)]
pub struct SyscallArgs {
    pub number: u64,
    pub arg1: u64,
    pub arg2: u64,
    pub arg3: u64,
    pub arg4: u64,
    pub arg5: u64,
    pub arg6: u64,
}

impl SyscallArgs {
    /// 새 syscall 인수 생성
    pub fn new(number: u64) -> Self {
        SyscallArgs {
            number,
            arg1: 0, arg2: 0, arg3: 0, arg4: 0, arg5: 0, arg6: 0,
        }
    }

    /// 인수 설정 (빌더 패턴)
    pub fn with_args(mut self, args: &[u64]) -> Self {
        for (i, &arg) in args.iter().enumerate().take(6) {
            match i {
                0 => self.arg1 = arg,
                1 => self.arg2 = arg,
                2 => self.arg3 = arg,
                3 => self.arg4 = arg,
                4 => self.arg5 = arg,
                5 => self.arg6 = arg,
                _ => break,
            }
        }
        self
    }
}

/// 시스템 호출 결과
#[repr(C)]
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct SyscallResult {
    pub return_value: i64,
    pub error_code: i32,
    pub success: bool,
}

impl SyscallResult {
    /// 성공 결과 생성
    pub fn ok(value: i64) -> Self {
        SyscallResult {
            return_value: value,
            error_code: 0,
            success: true,
        }
    }

    /// 에러 결과 생성
    pub fn error(code: i32) -> Self {
        SyscallResult {
            return_value: -1,
            error_code: code,
            success: false,
        }
    }
}

/// 시스템 호출 성능 통계
#[derive(Clone, Copy, Debug)]
pub struct SyscallStats {
    pub total_calls: u64,
    pub successful_calls: u64,
    pub failed_calls: u64,
    pub total_cycles: u64,  // CPU 사이클
    pub min_cycles: u64,
    pub max_cycles: u64,
}

impl SyscallStats {
    /// 새 통계 생성
    pub fn new() -> Self {
        SyscallStats {
            total_calls: 0,
            successful_calls: 0,
            failed_calls: 0,
            total_cycles: 0,
            min_cycles: u64::MAX,
            max_cycles: 0,
        }
    }

    /// 평균 사이클 계산
    pub fn avg_cycles(&self) -> u64 {
        if self.total_calls > 0 {
            self.total_cycles / self.total_calls
        } else {
            0
        }
    }

    /// 성공률 계산 (백분율)
    pub fn success_rate(&self) -> u8 {
        if self.total_calls > 0 {
            ((self.successful_calls * 100) / self.total_calls) as u8
        } else {
            0
        }
    }
}

