///
/// 사용법:
/// ```
/// define_syscall!(sys_write(fd: i32, buf: *const u8, count: usize) -> usize);
/// ```
macro_rules! define_syscall {
    ($name:ident($($param_name:ident: $param_type:ty),*) -> $return_type:ty) => {
        paste::paste! {
            fn [<$name>]($($param_name: $param_type),*) -> $return_type {
                // 이 매크로는 컴파일 시간에만 사용됨
                unimplemented!()
            }
        }
    };
}

/// 시스템 호출 래퍼
pub struct SyscallInterface;

impl SyscallInterface {
    /// 시스템 호출 처리 (표준화된 인터페이스)
    ///
    /// 성능 최적화:
    /// - Direct dispatch (match statement)
    /// - 최소한의 레지스터 이동
    /// - 캐시 친화적 구조
    pub fn call(args: &SyscallArgs) -> SyscallResult {
        match args.number {
            usermode::syscalls::SYS_EXIT => {
                Self::sys_exit(args.arg1 as i32);
                SyscallResult::ok(0)
            }
            usermode::syscalls::SYS_WRITE => {
                let ret = Self::sys_write(
                    args.arg1 as i32,
                    args.arg2 as *const u8,
                    args.arg3 as usize,
                );
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_READ => {
                let ret = Self::sys_read(
                    args.arg1 as i32,
                    args.arg2 as *mut u8,
                    args.arg3 as usize,
                );
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_OPEN => {
                let ret = Self::sys_open(args.arg1 as *const u8, args.arg2 as i32);
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_CLOSE => {
                let ret = Self::sys_close(args.arg1 as i32);
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_GETPID => {
                SyscallResult::ok(Self::sys_getpid())
            }
            usermode::syscalls::SYS_YIELD => {
                Self::sys_yield();
                SyscallResult::ok(0)
            }
            usermode::syscalls::SYS_GET_TIME => {
                SyscallResult::ok(Self::sys_get_time() as i64)
            }
            _ => {
                crate::println!("❌ Unknown syscall: {}", args.number);
                SyscallResult::error(1)
            }
        }
    }

    /// 호환성 인터페이스 (레거시 코드용)
    pub fn call_legacy(
        number: u64,
        arg1: u64,
        arg2: u64,
        arg3: u64,
        arg4: u64,
        arg5: u64,
    ) -> i64 {
        let args = SyscallArgs::new(number)
            .with_args(&[arg1, arg2, arg3, arg4, arg5]);
        let result = Self::call(&args);
        if result.success {
            result.return_value
        } else {
            result.return_value
        }
    }

