#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct SyscallResult {
    pub return_value: i64,
    pub error_code: i32,
    pub success: bool,
}

impl SyscallResult {
    /// 성공 결과 생성
    pub const fn ok(value: i64) -> Self {
        SyscallResult {
            return_value: value,
            error_code: 0,
            success: true,
        }
    }

    /// 에러 결과 생성
    pub const fn error(code: i32) -> Self {
        SyscallResult {
            return_value: -1,
            error_code: code,
            success: false,
        }
    }
}

/// 시스템 호출 성능 통계
#[derive(Clone, Copy, Debug)]
pub struct SyscallStats {
    pub total_calls: u64,
    pub successful_calls: u64,
    pub failed_calls: u64,
    pub total_cycles: u64,  // CPU 사이클
    pub min_cycles: u64,
    pub max_cycles: u64,
}

impl SyscallStats {
    /// 새 통계 생성
    pub fn new() -> Self {
        SyscallStats {
            total_calls: 0,
            successful_calls: 0,
            failed_calls: 0,
            total_cycles: 0,
            min_cycles: u64::MAX,
            max_cycles: 0,
        }
    }

    /// 통계 업데이트
    pub fn update(&mut self, cycles: u64, success: bool) {
        self.total_calls += 1;
        self.total_cycles += cycles;
        self.min_cycles = self.min_cycles.min(cycles);
        self.max_cycles = self.max_cycles.max(cycles);

        if success {
            self.successful_calls += 1;
        } else {
            self.failed_calls += 1;
        }
    }

    /// 평균 사이클 계산
    pub fn avg_cycles(&self) -> u64 {
        if self.total_calls > 0 {
            self.total_cycles / self.total_calls
        } else {
            0
        }
    }

    /// 성공률 계산 (백분율)
    pub fn success_rate(&self) -> u8 {
        if self.total_calls > 0 {
            ((self.successful_calls * 100) / self.total_calls) as u8
        } else {
            0
        }
    }
}

/// 전역 시스템 호출 통계 (원자적 접근)
pub static SYSCALL_STATS: SyscallStatsGlobal = SyscallStatsGlobal {
    total_calls: AtomicU64::new(0),
    successful_calls: AtomicU64::new(0),
    failed_calls: AtomicU64::new(0),
};

pub struct SyscallStatsGlobal {
    pub total_calls: AtomicU64,
    pub successful_calls: AtomicU64,
    pub failed_calls: AtomicU64,
}

impl SyscallStatsGlobal {
    /// 호출 기록
    pub fn record(&self, success: bool) {
        self.total_calls.fetch_add(1, Ordering::Relaxed);
        if success {
            self.successful_calls.fetch_add(1, Ordering::Relaxed);
        } else {
            self.failed_calls.fetch_add(1, Ordering::Relaxed);
        }
    }

    /// 통계 읽기
    pub fn snapshot(&self) -> SyscallStats {
        SyscallStats {
            total_calls: self.total_calls.load(Ordering::Relaxed),
            successful_calls: self.successful_calls.load(Ordering::Relaxed),
            failed_calls: self.failed_calls.load(Ordering::Relaxed),
            total_cycles: 0,
            min_cycles: 0,
            max_cycles: 0,
        }
    }
}

/// 시스템 호출 디스패처
pub struct SyscallDispatcher;

impl SyscallDispatcher {
    /// Syscall 테이블 (함수 포인터 배열)
    /// 성능: O(1) dispatch
    const SYSCALL_TABLE_SIZE: usize = 16;

    /// 중앙화된 호출 처리
    pub fn dispatch(args: &SyscallArgs) -> SyscallResult {
        let start_cycles = Self::rdtsc();

        let result = match args.number {
            usermode::syscalls::SYS_EXIT => {
                SyscallInterface::sys_exit(args.arg1 as i32);
                SyscallResult::ok(0)
            }
            usermode::syscalls::SYS_WRITE => {
                let ret = SyscallInterface::sys_write(
                    args.arg1 as i32,
                    args.arg2 as *const u8,
                    args.arg3 as usize,
                );
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_READ => {
                let ret = SyscallInterface::sys_read(
                    args.arg1 as i32,
                    args.arg2 as *mut u8,
                    args.arg3 as usize,
                );
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_OPEN => {
                let ret = SyscallInterface::sys_open(
                    args.arg1 as *const u8,
                    args.arg2 as i32,
                );
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_CLOSE => {
                let ret = SyscallInterface::sys_close(args.arg1 as i32);
                SyscallResult::ok(ret as i64)
            }
            usermode::syscalls::SYS_GETPID => {
                SyscallResult::ok(SyscallInterface::sys_getpid())
            }
            usermode::syscalls::SYS_YIELD => {
                SyscallInterface::sys_yield();
                SyscallResult::ok(0)
            }
            usermode::syscalls::SYS_GET_TIME => {
                SyscallResult::ok(SyscallInterface::sys_get_time() as i64)
            }
            _ => {
                crate::println!("❌ Unknown syscall: {}", args.number);
                SyscallResult::error(1)
            }
        };

        let end_cycles = Self::rdtsc();
        let cycles = end_cycles.saturating_sub(start_cycles);

        SYSCALL_STATS.record(result.success);

        result
    }

    /// RDTSC (Read Time Stamp Counter) - CPU 사이클 카운트
    #[inline]
    fn rdtsc() -> u64 {
        unsafe {
            core::arch::x86_64::_rdtsc()
        }
    }
}

/// 시스템 호출 인터페이스 (하위 수준 구현)
pub struct SyscallInterface;

impl SyscallInterface {
    /// 표준화된 호출 인터페이스
    pub fn call(args: &SyscallArgs) -> SyscallResult {
        SyscallDispatcher::dispatch(args)
    }

    /// 호환성 인터페이스 (레거시 코드용)
    pub fn call_legacy(
        number: u64,
        arg1: u64,
        arg2: u64,
        arg3: u64,
        arg4: u64,
        arg5: u64,
    ) -> i64 {
        let args = SyscallArgs::new(number)
            .with_args(&[arg1, arg2, arg3, arg4, arg5]);
        let result = Self::call(&args);
        if result.success {
            result.return_value
        } else {
            result.return_value
        }
    }

    /// 빠른 시스템 호출 핸들러 (x86-64 SYSCALL 명령어)
    pub fn handle_syscall_fast(
        rax: u64,
        rdi: u64,
        rsi: u64,
        rdx: u64,
        r10: u64,
        r8: u64,
    ) -> i64 {
        // x86-64 System V ABI 호출 규약:
        // RAX = syscall number
        // RDI = arg1
        // RSI = arg2
        // RDX = arg3
        // R10 = arg4 (RCX는 RIP 저장용)
        // R8 = arg5
        // R9 = arg6

        let args = SyscallArgs::new(rax)
            .with_args(&[rdi, rsi, rdx, r10, r8]);

        let result = SyscallDispatcher::dispatch(&args);
        result.return_value
    }

    // ===== Syscall 구현 =====

    /// exit(status) - 프로세스 종료
    fn sys_exit(status: i32) -> ! {
        crate::println!("👤 Process exit with status: {}", status);
        loop {
            unsafe { core::arch::asm!("hlt"); }
        }
    }

    /// write(fd, buf, count) - 버퍼 쓰기
    fn sys_write(fd: i32, buf: *const u8, count: usize) -> usize {
        if fd == 1 {
            // stdout
            unsafe {
                for i in 0..count {
                    let ch = *buf.add(i) as char;
                    crate::print!("{}", ch);
                }
            }
            count
        } else {
            0
        }
    }

    /// read(fd, buf, count) - 버퍼 읽기
    fn sys_read(fd: i32, buf: *mut u8, count: usize) -> usize {
        if fd == 0 {
            // stdin: 현재 미지원
            0
        } else {
            0
        }
    }

    /// open(filename, flags) - 파일 열기
    fn sys_open(filename: *const u8, flags: i32) -> i32 {
        unsafe {
            let mut name = [0u8; 256];
            let mut i = 0;
            while *filename.add(i) != 0 && i < 255 {
                name[i] = *filename.add(i);
                i += 1;
            }
            crate::println!("📂 open() called for file at 0x{:x}, flags={}",
                filename as u64, flags);
        }
        1
    }

    /// close(fd) - 파일 닫기
    fn sys_close(fd: i32) -> i32 {
        crate::println!("🔒 close(fd={})", fd);
        0
    }

    /// getpid() - 프로세스 ID 획득
    fn sys_getpid() -> i64 {
        1
    }

    /// yield() - CPU 양보
    fn sys_yield() {
        crate::println!("⏸ Thread yielding");
    }

    /// get_time() - 시간 획득 (밀리초)
    fn sys_get_time() -> u64 {
        0
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_syscall_args() {
        let args = SyscallArgs::new(1)
            .with_args(&[10, 20, 30]);

        assert_eq!(args.number, 1);
        assert_eq!(args.arg1, 10);
        assert_eq!(args.arg2, 20);
        assert_eq!(args.arg3, 30);
    }

    #[test]
    fn test_syscall_result_ok() {
        let result = SyscallResult::ok(42);
        assert!(result.success);
        assert_eq!(result.return_value, 42);
        assert_eq!(result.error_code, 0);
    }

    #[test]
    fn test_syscall_result_error() {
        let result = SyscallResult::error(5);
        assert!(!result.success);
        assert_eq!(result.error_code, 5);
        assert_eq!(result.return_value, -1);
    }

    #[test]
    fn test_syscall_stats() {
        let mut stats = SyscallStats::new();

        stats.update(100, true);
        stats.update(200, true);
        stats.update(150, false);

        assert_eq!(stats.total_calls, 3);
        assert_eq!(stats.successful_calls, 2);
        assert_eq!(stats.failed_calls, 1);
        assert_eq!(stats.min_cycles, 100);
        assert_eq!(stats.max_cycles, 200);
        assert_eq!(stats.avg_cycles(), 150);
        assert_eq!(stats.success_rate(), 66);
    }

    #[test]
    fn test_syscall_interface() {
        let args = SyscallArgs::new(usermode::syscalls::SYS_GETPID);
        let result = SyscallInterface::call(&args);

        assert!(result.success);
        assert_eq!(result.return_value, 1);
    }

    #[test]
    fn test_legacy_interface() {
        let result = SyscallInterface::call_legacy(
            usermode::syscalls::SYS_GETPID,
            0, 0, 0, 0, 0
        );
        assert_eq!(result, 1);
    }

    #[test]
    fn test_syscall_dispatch() {
        let args = SyscallArgs::new(usermode::syscalls::SYS_GETPID);
        let result = SyscallDispatcher::dispatch(&args);

        assert!(result.success);
        assert_eq!(result.return_value, 1);
    }

    #[test]
    fn test_unknown_syscall() {
        let args = SyscallArgs::new(9999);
        let result = SyscallDispatcher::dispatch(&args);

        assert!(!result.success);
        assert_eq!(result.error_code, 1);
    }

    #[test]
    fn test_global_stats_recording() {
        let initial = SYSCALL_STATS.snapshot();
        SYSCALL_STATS.record(true);
        SYSCALL_STATS.record(false);

        let after = SYSCALL_STATS.snapshot();
        assert_eq!(after.total_calls, initial.total_calls + 2);
    }
}
